{
  "candidate_id": "phase3-acceptance-mg-iii-candidate",
  "created_by_agent_call_id": "agent-call-001",
  "proposed_rules": [
    {
      "official_code": "IN-01",
      "components": [
        {
          "title": "年龄和性别要求",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-01.age.lower.bound",
                  "subject": "受试者",
                  "attribute": "年龄",
                  "comparator": "gte",
                  "value": 18,
                  "unit": "周岁",
                  "source_term": "年龄",
                  "source_clause": "年龄18~75周岁（包括边界值）"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-01.age.upper.bound",
                  "subject": "受试者",
                  "attribute": "年龄",
                  "comparator": "lte",
                  "value": 75,
                  "unit": "周岁",
                  "source_term": "年龄",
                  "source_clause": "年龄18~75周岁（包括边界值）"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-01.gender",
                  "subject": "受试者",
                  "attribute": "性别",
                  "comparator": "in",
                  "value": ["男", "女"],
                  "source_term": "男女",
                  "source_clause": "男女不限"
                }
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "demographic_data",
              "due_stage": "screening",
              "description": "筛选时收集人口学资料（年龄、性别）以核对入选标准IN-01"
            },
            {
              "fact_type": "demographic_data",
              "due_stage": "baseline",
              "description": "基线时再次审核人口学资料（年龄、性别）以核对入选标准IN-01"
            }
          ],
          "source_span_ids": ["phase3-acceptance-mg-iii-snapshot::body.p548"],
          "source_excerpts": ["年龄18~75周岁（包括边界值），男女不限；"]
        }
      ]
    },
    {
      "official_code": "IN-02",
      "components": [
        {
          "title": "季节性过敏性鼻炎诊断、病史和sIgE",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-02.diagnosis",
                  "subject": "受试者",
                  "attribute": "符合季节性过敏性鼻炎的诊断",
                  "comparator": "eq",
                  "value": true,
                  "requires_professional_judgment": true,
                  "source_clause": "参照《中国变应性鼻炎诊断和治疗指南（2022年，修订版）》受试者符合季节性过敏性鼻炎的诊断"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-02.history.duration",
                  "subject": "受试者",
                  "attribute": "既往明确病史持续时间",
                  "comparator": "gte",
                  "value": 2,
                  "unit": "年",
                  "source_term": "既往明确病史",
                  "source_clause": "既往明确病史≥2年"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-02.sige",
                  "subject": "受试者",
                  "attribute": "存在符合指南对SAR诊断标准的sIgE检测结果",
                  "comparator": "exists",
                  "value": true,
                  "source_clause": "筛选/导入期至少一种与当前季节或同期过敏性鼻炎发病相关的sIgE检测结果符合指南对SAR的诊断标准"
                }
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "clinical_diagnosis_and_sige",
              "due_stage": "screening",
              "description": "筛选时确认季节性过敏性鼻炎诊断、病史和sIgE检测结果以核对IN-02"
            },
            {
              "fact_type": "clinical_diagnosis_and_sige",
              "due_stage": "baseline",
              "description": "基线时再次确认季节性过敏性鼻炎诊断、病史和sIgE检测结果以核对IN-02"
            }
          ],
          "source_span_ids": ["phase3-acceptance-mg-iii-snapshot::body.p549"],
          "source_excerpts": ["参照《中国变应性鼻炎诊断和治疗指南（2022年，修订版）》受试者符合季节性过敏性鼻炎的诊断，既往明确病史≥2年，筛选/导入期至少一种与当前季节或同期过敏性鼻炎发病相关的sIgE检测结果符合指南对SAR的诊断标准；"]
        }
      ]
    },
    {
      "official_code": "IN-03",
      "components": [
        {
          "title": "花粉季节药物使用及症状控制不佳",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "logical",
                "operator": "any",
                "children": [
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-03.nasal.corticosteroid",
                      "subject": "受试者",
                      "attribute": "在当前或既往同期花粉季节使用鼻喷糖皮质激素",
                      "comparator": "eq",
                      "value": true,
                      "source_clause": "受试者在当前或既往同期花粉季节，使用鼻喷糖皮质激素"
                    }
                  },
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-03.other.sar.med",
                      "subject": "受试者",
                      "attribute": "在当前或既往同期花粉季节使用其他治疗SAR药物",
                      "comparator": "eq",
                      "value": true,
                      "source_clauses": ["受试者在当前或既往同期花粉季节，使用", "或其他治疗SAR药物"]
                    }
                  }
                ]
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-03.poor.control",
                  "subject": "受试者",
                  "attribute": "SAR症状控制不佳",
                  "comparator": "eq",
                  "value": true,
                  "requires_professional_judgment": true,
                  "source_clause": "SAR症状控制不佳"
                }
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "treatment_history_and_response",
              "due_stage": "screening",
              "description": "筛选时收集花粉季节用药史和症状控制情况以核对IN-03"
            },
            {
              "fact_type": "treatment_history_and_response",
              "due_stage": "baseline",
              "description": "基线时再次收集花粉季节用药史和症状控制情况以核对IN-03"
            }
          ],
          "source_span_ids": ["phase3-acceptance-mg-iii-snapshot::body.p550"],
          "source_excerpts": ["受试者在当前或既往同期花粉季节，使用鼻喷糖皮质激素或其他治疗SAR药物（抗组胺药、白三烯受体拮抗剂等），SAR症状控制不佳；"]
        }
      ]
    }
  ]
}

