{
  "candidate_id": "phase3-acceptance-mg-iii-candidate",
  "created_by_agent_call_id": "agent-call-002",
  "proposed_rules": [
    {
      "official_code": "IN-04",
      "components": [
        {
          "title": "筛选时症状评分标准",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-04.screening.itnss",
                  "subject": "受试者",
                  "attribute": "iTNSS评分",
                  "comparator": "gte",
                  "value": 6,
                  "unit": "分",
                  "source_term": "iTNSS评分",
                  "source_clause": "筛选时iTNSS评分≥6分"
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-04.screening.nasal_congestion",
                  "subject": "受试者",
                  "attribute": "鼻塞评分",
                  "comparator": "gte",
                  "value": 2,
                  "unit": "分",
                  "source_term": "鼻塞",
                  "source_clause": "鼻塞≥2分"
                }
              },
              {
                "kind": "logical",
                "operator": "any",
                "children": [
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-04.screening.running_nose",
                      "subject": "受试者",
                      "attribute": "流鼻涕评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": "流鼻涕",
                      "source_clause": "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                    }
                  },
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-04.screening.itchy_nose",
                      "subject": "受试者",
                      "attribute": "鼻痒评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": "鼻痒",
                      "source_clause": "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                    }
                  },
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-04.screening.sneezing",
                      "subject": "受试者",
                      "attribute": "打喷嚏评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": "打喷嚏",
                      "source_clause": "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                    }
                  }
                ]
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "symptom_scores",
              "due_stage": "screening",
              "description": "筛选时核对iTNSS评分、鼻塞评分及流鼻涕/鼻痒/打喷嚏任一症状评分"
            }
          ],
          "source_span_ids": [
            "phase3-acceptance-mg-iii-snapshot::body.p551",
            "phase3-acceptance-mg-iii-snapshot::body.p552"
          ],
          "source_excerpts": [
            "筛选时和基线时需满足以下标准：",
            "筛选时iTNSS评分≥6分，鼻塞≥2分，流鼻涕、鼻痒和打喷嚏三种症状之一≥2分；"
          ]
        },
        {
          "title": "基线时症状评分标准",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-04.baseline.itnss",
                  "subject": "受试者",
                  "attribute": "基线iTNSS",
                  "comparator": "gte",
                  "value": 6,
                  "unit": "分",
                  "source_term": "iTNSS",
                  "source_clauses": [
                    "基线时iTNSS评分≥6分",
                    "基线iTNSS为导入期最后3个时间点和D1的1个时间点（共4个）的iTNSS均值"
                  ]
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-04.baseline.rtnss",
                  "subject": "受试者",
                  "attribute": "基线rTNSS",
                  "comparator": "gte",
                  "value": 6,
                  "unit": "分",
                  "source_term": "rTNSS",
                  "source_clauses": [
                    "rTNSS≥6分",
                    "基线rTNSS为导入期最后6个时间点和D1的1个时间点（共7个）的rTNSS均值（总评分和单项症状评分均采用均值）"
                  ]
                }
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-04.baseline.nasal_congestion",
