                      "attribute": "鼻痒评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": "鼻痒",
                      "source_clause": "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                    }
                  },
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-04.baseline.sneezing",
                      "subject": "受试者",
                      "attribute": "打喷嚏评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": "打喷嚏",
                      "source_clause": "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                    }
                  }
                ]
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "baseline_symptom_scores",
              "due_stage": "baseline",
              "description": "基线时核对基线iTNSS、基线rTNSS、鼻塞评分及流鼻涕/鼻痒/打喷嚏任一症状评分，评分按注释计算"
